'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const source=fs.readFileSync(path.join(__dirname,'app.js'),'utf8');
const start=source.indexOf('function normaliseEchoDevice('),end=source.indexOf('function displayDim(',start);
const {normaliseEchoDevice:n,confirmedPlaybackMode:m,echoDeviceAvailable:a}=new Function(source.slice(start,end)+';return {normaliseEchoDevice,confirmedPlaybackMode,echoDeviceAvailable};')();
assert.equal(n('echo-id'),'echo-id');assert.equal(n(null),'');assert.equal(n(' '),'');assert.equal(n('x'.repeat(257)),'');
assert.equal(m({connected:true,deviceId:'echo-id'},'echo-id'),'echo');
assert.equal(m({connected:true,deviceId:'other'},'echo-id'),'wifi');
assert.equal(m({connected:false,deviceId:'echo-id'},'echo-id'),'wifi');
assert.equal(m({connected:true,error:'x',deviceId:'echo-id'},'echo-id'),'wifi');
assert.equal(m({connected:true,deviceId:''},''),'wifi');
assert.equal(a([{id:'echo-id',restricted:false}], 'echo-id'),true);
assert.equal(a([{id:'echo-id',restricted:true}], 'echo-id'),false);
assert.equal(a([{id:'other',restricted:false}], 'echo-id'),false);
assert.equal(a(null,'echo-id'),false);
assert.ok(source.includes("openOverlay('devices',prefs.echoDeviceId?'echo-transfer':'echo-bind')"));
assert.ok(source.includes("if(!valid())return;"));
assert.ok(source.includes("list.filter(d=>d.id!==prefs.echoDeviceId)"));
assert.ok(source.includes("prefs.echoDeviceId=id;save();"));
assert.ok(source.includes("live.command('device',id)"));
console.log('Echo playback mode checks passed');
